import{_ as t}from"./chunks/isaac-sim.fbmzTwGQ.js";import{_ as a,o as i,c as e,a5 as o}from"./chunks/framework.BMR-TWOq.js";const m=JSON.parse('{"title":"Isaac Sim","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"software/simulator/isaac-sim.md","filePath":"software/simulator/isaac-sim.md","lastUpdated":1794576042000}'),n={name:"software/simulator/isaac-sim.md"};function r(l,s,d,h,c,p){return i(),e("div",null,[...s[0]||(s[0]=[o('<h1 id="isaac-sim" tabindex="-1">Isaac Sim <a class="header-anchor" href="#isaac-sim" aria-label="Permalink to &quot;Isaac Sim&quot;">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p><strong>Isaac Sim simulator for the RBQ quadruped robot.</strong></p><p>Isaac Sim runs the <strong>full RBQ software stack</strong> (Motion / Vision) against NVIDIA Isaac Sim physics, like <a href="/RBQ/nightly/software/simulator/mujoco.html">MuJoCo</a> and <a href="/RBQ/nightly/software/simulator/gazebo.html">Gazebo</a>. It joins the running RBQ stack as a DDS peer on the same topics, so the robot software runs unchanged. It uses the same robot model as the <a href="/RBQ/nightly/software/simulator/rbq-lab.html">Isaac Lab</a> training environment, and adds USD worlds with stairs, ramps and rough terrain.</p><table tabindex="0"><thead><tr><th style="text-align:center;">Isaac Sim</th></tr></thead><tbody><tr><td style="text-align:center;"><img src="'+t+`" alt="Isaac Sim" width="600"></td></tr></tbody></table><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li>NVIDIA RTX GPU and about 30 GB of free disk</li><li>Ubuntu 22.04</li><li>Isaac Sim 5.1.0 and Isaac Lab, installed by the script below into the same conda environment (<code>rbq-lab</code>) as Isaac Lab</li></ul><h2 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;Layout&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Path</th><th>Description</th></tr></thead><tbody><tr><td><code>rbq_simulator/rbq_sim/rbq_sim/</code></td><td>Simulator sources (Python)</td></tr><tr><td><code>rbq_simulator/rbq_sim/worlds/</code></td><td>USD worlds that ship with the package</td></tr><tr><td><code>rbq_simulator/rbq_sim/scripts/</code></td><td>Run / environment scripts</td></tr><tr><td><code>scripts/issac_sim.bash</code></td><td>Starts Motion, Isaac Sim and the web UI together</td></tr><tr><td><code>scripts/install/isaacsim.bash</code></td><td>Installs Isaac Sim</td></tr></tbody></table><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Meaning</th></tr></thead><tbody><tr><td><code>--world &lt;name&gt;</code></td><td>World to load. Default <code>empty</code>. See <a href="#worlds">Worlds</a></td></tr><tr><td><code>--headless</code></td><td>Run without the Isaac Sim window</td></tr><tr><td><code>-i</code>, <code>--interface &lt;name&gt;</code></td><td>DDS network interface. Default <code>lo</code></td></tr></tbody></table><p><code>scripts/issac_sim.bash</code> also takes <code>--vision</code> (start the Vision stack) and <code>--ros</code> (start the ROS 2 driver and RViz).</p><h2 id="worlds" tabindex="-1">Worlds <a class="header-anchor" href="#worlds" aria-label="Permalink to &quot;Worlds {#worlds}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Kind</th><th><code>--world</code></th><th>Notes</th></tr></thead><tbody><tr><td>Flat ground</td><td><code>empty</code>, <code>raceway</code>, <code>maze</code></td><td>No download</td></tr><tr><td>Isaac Sim samples</td><td><code>grid</code>, <code>office</code>, <code>hospital</code>, <code>simple_room</code>, <code>warehouse</code>, <code>depot</code>, <code>warehouse_shelves</code>, <code>warehouse_forklifts</code></td><td>Downloaded from NVIDIA on first use</td></tr><tr><td>Bundled</td><td><code>stairs_course</code>, <code>two_floor_office</code>, <code>terrain_park</code></td><td>Work offline</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Bundled world</th><th>Contents</th></tr></thead><tbody><tr><td><code>stairs_course</code></td><td>32 x 16 m hall with stairs (0.10 m and 0.15 m rise), 10° / 15° / 20° ramps, rough blocks, stepping stones and curbs</td></tr><tr><td><code>two_floor_office</code></td><td>Two floors joined by a switchback staircase (0.15 m x 20 steps), with room loops on both floors</td></tr><tr><td><code>terrain_park</code></td><td>40 x 40 m outdoor park with pyramid stairs, rough terrain, a 15° hill and a raised plaza with stairs and a ramp</td></tr></tbody></table><h3 id="using-your-own-usd" tabindex="-1">Using your own USD <a class="header-anchor" href="#using-your-own-usd" aria-label="Permalink to &quot;Using your own USD&quot;">​</a></h3><p>Add an entry to <code>WORLDS</code> in <code>rbq_simulator/rbq_sim/rbq_sim/worlds.py</code>, then run it by name:</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;my_site&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;spawn&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.30</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">),   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># x, y, z [m], yaw [rad]</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">            &quot;usd&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/path/to/my_site.usd&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># absolute path, or a file:// / omniverse:// URL</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/issac_sim.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --world</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my_site</span></span></code></pre></div><p>The USD replaces the flat ground, so it must contain a floor with collision. The robot starts sitting at the spawn pose. If the floor is not at height 0, raise <code>z</code> by the floor height.</p><h2 id="run-with-the-full-rbq-stack-local" tabindex="-1">Run with the full RBQ stack (Local) <a class="header-anchor" href="#run-with-the-full-rbq-stack-local" aria-label="Permalink to &quot;Run with the full RBQ stack (Local)&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Clone</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/RainbowRobotics/RBQ.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> RBQ</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Install Isaac Sim (first time only, as a normal user; only the apt step asks for sudo)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/install/isaacsim.bash</span></span></code></pre></div><p><strong>All at once</strong> — Motion, Isaac Sim and the web UI in separate terminal tabs:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/issac_sim.bash</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/issac_sim.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --world</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stairs_course</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/issac_sim.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --headless</span></span></code></pre></div><p><strong>One by one</strong> — the RBQ stack and the simulator in two terminals:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/start_motion.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --sim</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                   # terminal 1, asks for sudo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbq_simulator/rbq_sim/scripts/run.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --world</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stairs_course</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # terminal 2</span></span></code></pre></div><p>Open <code>http://127.0.0.1:8080</code> in a browser to drive the robot (sign in with <code>rb</code> / <code>rainbow2026</code>). The first start takes a few minutes while Isaac Sim builds its shader cache.</p><h2 id="control-period" tabindex="-1">Control period <a class="header-anchor" href="#control-period" aria-label="Permalink to &quot;Control period&quot;">​</a></h2><p>Isaac Sim runs slower than real time: about 0.85x headless and about 0.6x with the window open. The simulator keeps Motion in step with simulation time, so the robot software still sees a 2 ms control period:</p><ul><li>Physics runs at 1 kHz. Every 2 ms of simulation time the simulator sends its state and waits for Motion&#39;s reply before it moves on.</li><li>Motion therefore runs exactly one control cycle per 2 ms of simulation time, however slow the rendering is. The robot moves slower on screen, not differently.</li><li>Every 5 seconds the console prints a line such as <code>lockstep ON acked 1472/1472 timeouts 0</code>. <code>timeouts 0</code> means no control cycle was skipped.</li><li>Without Motion the simulator holds the sitting pose and runs at real-time pace.</li></ul><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">NOTE — DDS networking</p><p>The simulator shares <strong>DDS domain 0</strong> on the loopback interface (<code>lo</code>) with the RBQ stack. Most hosts have no multicast on <code>lo</code>, so <code>run.bash</code> loads <code>rbq_simulator/rbq_sim/cyclonedds_sim.xml</code>. Run only one simulator at a time: Isaac Sim, MuJoCo and Gazebo use the same topics.</p></div></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/RBQ/nightly/software/simulator/mujoco.html">MuJoCo</a> — MuJoCo simulator</li><li><a href="/RBQ/nightly/software/simulator/gazebo.html">Gazebo</a> — Ignition Gazebo simulator</li><li><a href="/RBQ/nightly/software/simulator/rbq-lab.html">Isaac Lab</a> — RL training environment on the same robot model</li><li><a href="/RBQ/nightly/software/simulator/overview.html">Simulator overview</a></li></ul>`,33)])])}const b=a(n,[["render",r]]);export{m as __pageData,b as default};
